import{_ as s,o as c,c as a}from"./chunks/framework.BnuTGVYS.js";const d=JSON.parse('{"title":"Kafka 部署、运维与故障排查","titleTemplate":":title · 知行笔记","description":"从连接失败、消息积压、ISR 收缩、磁盘上涨等现象入手，按顺序检查并验证处理结果。命令以 Apache Kafka 4.0.2、Linux Bash、普通消费者组 为例；这是一套固定版本示例。已有集群先确认版本与部署方式，再使用它对应的工具","frontmatter":{"title":"Kafka 部署、运维与故障排查","titleTemplate":":title · 知行笔记","description":"从连接失败、消息积压、ISR 收缩、磁盘上涨等现象入手，按顺序检查并验证处理结果。命令以 Apache Kafka 4.0.2、Linux Bash、普通消费者组 为例；这是一套固定版本示例。已有集群先确认版本与部署方式，再使用它对应的工具","kb":"{\\"site\\":{\\"title\\":\\"知行笔记\\",\\"description\\":\\"把实践整理成知识，让经验随时可查。\\",\\"publicRepository\\":\\"alcq77/alcq77.github.io\\",\\"localOnly\\":false,\\"support\\":{\\"wechat\\":\\"assets/support/wechat.jpg\\",\\"alipay\\":\\"assets/support/alipay.jpg\\"}},\\"docs\\":[{\\"id\\":\\"docker-compose-operations-commands\\",\\"title\\":\\"Docker 与 Docker Compose 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kafka-operations\\",\\"title\\":\\"Kafka 部署、运维与故障排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-internals\\",\\"title\\":\\"Kafka 核心机制与源码排查\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kafka-reliability\\",\\"title\\":\\"Kafka 消息生产、消费与可靠性实践\\",\\"module\\":\\"mq-operations\\",\\"category\\":\\"消息队列\\"},{\\"id\\":\\"kubernetes-operations-commands\\",\\"title\\":\\"Kubernetes 常用运维命令\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-cluster-troubleshooting\\",\\"title\\":\\"Kubernetes 集群搭建、维护与故障排查\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"kubernetes-application-practice\\",\\"title\\":\\"Kubernetes 应用部署与配置实践\\",\\"module\\":\\"container-operations\\",\\"category\\":\\"容器运维\\"},{\\"id\\":\\"linux-system-status-commands\\",\\"title\\":\\"Linux 常用系统状态查看命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-service-check-start-troubleshooting\\",\\"title\\":\\"Linux 服务检查、启动与排障\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-systemd-autostart\\",\\"title\\":\\"Linux 服务开机自启与 systemd 管理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-server-operations-commands\\",\\"title\\":\\"Linux 服务器常用运维命令\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-kernel-troubleshooting\\",\\"title\\":\\"Linux 内核问题排查与处理\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"linux-performance-troubleshooting\\",\\"title\\":\\"Linux 性能瓶颈排查与优化\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"},{\\"id\\":\\"nginx-operations\\",\\"title\\":\\"Nginx 配置、部署与日常运维\\",\\"module\\":\\"linux-operations\\",\\"category\\":\\"Linux 运维\\"}],\\"doc\\":{\\"id\\":\\"kafka-operations\\",\\"title\\":\\"Kafka 部署、运维与故障排查\\",\\"category\\":\\"消息队列\\"},\\"content\\":\\"\\\\u003cdiv class=\\\\\\"article-head\\\\\\">\\\\u003cdiv class=\\\\\\"eyebrow\\\\\\">消息队列\\\\u003c/div>\\\\u003ch1>Kafka 部署、运维与故障排查\\\\u003c/h1>\\\\u003cdiv class=\\\\\\"article-meta\\\\\\">\\\\u003cspan class=\\\\\\"author-avatar\\\\\\">知\\\\u003c/span>\\\\u003cspan>知行笔记\\\\u003c/span>\\\\u003cspan class=\\\\\\"meta-dot\\\\\\">·\\\\u003c/span>\\\\u003cspan>约 37 分钟阅读\\\\u003c/span>\\\\u003c/div>\\\\u003cdiv class=\\\\\\"tag-row\\\\\\">\\\\u003cspan class=\\\\\\"tag\\\\\\">kafka\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">mq\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">kraft\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">operations\\\\u003c/span>\\\\u003cspan class=\\\\\\"tag\\\\\\">troubleshooting\\\\u003c/span>\\\\u003c/div>\\\\u003c/div>\\\\u003carticle class=\\\\\\"markdown-body\\\\\\">\\\\u003cp>从连接失败、消息积压、ISR 收缩、磁盘上涨等现象入手，按顺序检查并验证处理结果。命令以 \\\\u003cstrong>Apache Kafka 4.0.2、Linux Bash、普通消费者组\\\\u003c/strong>为例；这是一套固定版本示例。已有集群先确认版本与部署方式，再使用它对应的工具。4.x 使用 KRaft，旧 ZooKeeper 集群的修复和迁移不能直接套用。\\\\u003c/p>\\\\n\\\\u003cp>生产消费代码见 \\\\u003ca href=\\\\\\"kafka-reliability.html\\\\\\">Kafka 消息生产、消费与可靠性实践\\\\u003c/a>，需要追到内部实现时看 \\\\u003ca href=\\\\\\"kafka-internals.html\\\\\\">Kafka 核心机制与源码排查\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"1-执行前先确认环境和权限\\\\\\">1. 执行前先确认环境和权限\\\\u003c/h2>\\\\n\\\\u003cp>Kafka 工具可以在能访问集群的管理机上执行，磁盘、进程、日志命令则需要登录到对应 Broker 主机。以下变量在同一个 Bash 终端中设置，后续示例沿用它们。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> KAFKA_HOME=/opt/kafka                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 改成实际 Kafka 安装目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> BS=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;broker1.example.com:9092,broker2.example.com:9092&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 客户端入口，不能填 Controller 端口\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> TOPIC=orders                               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 本次排查的主题\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> GROUP=orders-worker                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 本次排查的消费者组\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cd\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$KAFKA_HOME\\\\u003c/span>&quot;\\\\u003c/span>                                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 后面的 bin/ 从安装目录执行\\\\u003c/span>\\\\nbin/kafka-topics.sh --version                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看这套命令行工具的版本\\\\u003c/span>\\\\njava -version                                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看当前终端使用的 JDK\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：服务运行在 \\\\u003ccode>/srv/kafka\\\\u003c/code>，管理机却使用 \\\\u003ccode>/opt/kafka\\\\u003c/code> 中另一版本的脚本，应先核对差异。命令行工具的版本不等于远端 Broker 的版本，后者还要查部署镜像、安装清单或启动日志。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">ADMIN=()                                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 无认证的隔离实验集群使用空参数\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 已有安全集群改用下面两行；文件由管理员提供，不能用空文件绕过认证\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># export CLIENT_CONFIG=&quot;$HOME/.config/kafka/admin.properties&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># ADMIN=(--command-config &quot;$CLIENT_CONFIG&quot;)       # 管理命令追加认证、TLS 参数\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>&quot;${ADMIN[@]}&quot;\\\\u003c/code> 是 Bash 数组展开，空数组不增加参数；安全集群会展开为两个独立参数。生产者用 \\\\u003ccode>--producer.config\\\\u003c/code>，消费者用 \\\\u003ccode>--consumer.config\\\\u003c/code>，不能把管理命令的 \\\\u003ccode>--command-config\\\\u003c/code> 原样放过去。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">id\\\\u003c/span>                                               \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看当前用户和所属组\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> -l                                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看获准执行的管理操作\\\\u003c/span>\\\\nsystemctl status kafka --no-pager -l              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看 systemd 服务状态，服务名按实际替换\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> kafka                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对启动用户、程序路径和配置文件\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：查询 Kafka 的授权由 Kafka ACL 决定，Linux 上使用 root 不会自动获得 Topic 权限。查看进程用服务所属用户；读取其他用户日志、端口归属或操作 systemd 时才按需使用 sudo。没有 sudo 授权时请管理员执行对应步骤，不改成 \\\\u003ccode>chmod -R 777\\\\u003c/code>。\\\\u003c/p>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>展开：安装排查工具和 JDK\\\\u003c/summary>\\\\n\\\\u003cp>按系统选择一组。包安装在被检查的主机；管理机只需 JDK、Kafka 工具及必要的网络工具。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> /etc/os-release                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认发行版，避免混用软件源\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Ubuntu / Debian：安装 JDK 和诊断工具\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get update                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 更新软件索引\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> apt-get install default-jdk curl ca-certificates tar procps iproute2 sysstat lsof openssl\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># RHEL / Rocky / AlmaLinux：使用系统已有 dnf 仓库\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># sudo dnf install java-17-openjdk-devel curl ca-certificates tar procps-ng iproute sysstat lsof openssl\\\\u003c/span>\\\\njava -version                                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># Kafka 4.0 的 Broker 和工具需要 Java 17+\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">command\\\\u003c/span> -v iostat pidstat jcmd lsof                \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认工具已进入 PATH\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>iostat\\\\u003c/code>、\\\\u003ccode>pidstat\\\\u003c/code> 由 \\\\u003ccode>sysstat\\\\u003c/code> 提供，\\\\u003ccode>jcmd\\\\u003c/code> 由 JDK 提供。容器精简镜像不一定包含它们，优先在宿主机或已有诊断环境操作，不临时修改运行中的业务镜像。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7只从现有批准仓库安装基础工具，JDK另行核对，不能假设基础仓库提供Java 17：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> yum install curl ca-certificates tar procps-ng iproute sysstat lsof openssl \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 安装网络、进程与磁盘诊断工具\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">uname\\\\u003c/span> -m                                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对CPU架构，不能混用x64与ARM构建\\\\u003c/span>\\\\nldd --version                                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看glibc版本，与所选JDK发行包要求对照\\\\u003c/span>\\\\nyum --showduplicates list java-17-openjdk-devel  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查询候选；无包时不添加其他发行版的源\\\\u003c/span>\\\\njava -version                                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看当前JDK；Java 8/11不能运行本文4.0 Broker示例\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：原Kafka运行在Java 8/11时，先确认原Kafka版本，维护时沿用它匹配的工具；不要为运行本文示例原地升级生产JDK或Kafka。本文实验的Broker和命令行工具至少需要Java 17，优先在受维护的管理机或实验机上准备。\\\\u003c/p>\\\\n\\\\u003cp>确实需要在CentOS 7使用JDK 17时，先按JDK供应方的支持平台、架构和glibc要求选发行包，完成来源及校验和核对。可参考\\\\u003ca href=\\\\\\"https://adoptium.net/installation/archives\\\\\\">JDK归档安装方法\\\\u003c/a>，安装方法本身不代表任意构建都支持CentOS 7。若已将审核过的JDK解压到 \\\\u003ccode>/opt/jdk-17\\\\u003c/code>，仅在当前终端指定它：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> JAVA_HOME=/opt/jdk-17                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 改为已验证兼容的JDK目录，不修改整机默认Java\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> PATH=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$JAVA_HOME\\\\u003c/span>/bin:\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PATH\\\\u003c/span>&quot;\\\\u003c/span>              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前终端优先使用这一套JDK\\\\u003c/span>\\\\njava -version                                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 验证实际运行版本，不能出现GLIBC缺失等错误\\\\u003c/span>\\\\njavac -version                                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 编译示例时确认包含编译器\\\\u003c/span>\\\\njcmd -l                                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 用获准身份列出可见JVM，附加工具应匹配目标JDK\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：出现 \\\\u003ccode>GLIBC_2.xx not found\\\\u003c/code>时不要替换系统glibc，改选供应方确认兼容的构建或换到受维护系统。当前终端的 \\\\u003ccode>JAVA_HOME\\\\u003c/code>不会自动改变systemd服务，服务环境以其unit配置为准。旧sysstat字段按本机表头阅读；cgroup v1检查见\\\\u003ca href=\\\\\\"linux-kernel-troubleshooting.html\\\\\\">Linux内核排查\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003ch2 id=\\\\\\"2-新建一个可以验证收发的实验环境\\\\\\">2. 新建一个可以验证收发的实验环境\\\\u003c/h2>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>展开：下载二进制包，启动单节点 KRaft\\\\u003c/summary>\\\\n\\\\u003cp>在新建的实验目录执行。单节点只用于学习、验证命令，不提供副本容错。这里绑定回环地址，远程客户端无法连接。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mkdir\\\\u003c/span> -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/kafka-lab&quot;\\\\u003c/span>                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 新建实验工作目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cd\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/kafka-lab&quot;\\\\u003c/span>                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 后续下载均保存在这里\\\\u003c/span>\\\\ncurl -fLO https://archive.apache.org/dist/kafka/4.0.2/kafka_2.13-4.0.2.tgz \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 下载固定版本\\\\u003c/span>\\\\ncurl -fLO https://archive.apache.org/dist/kafka/4.0.2/kafka_2.13-4.0.2.tgz.sha512 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 下载校验值\\\\u003c/span>\\\\nEXPECTED_SHA512=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-subst\\\\\\">$(sed &#x27;1s/^[^:]*: //&#x27; kafka_2.13-4.0.2.tgz.sha512 | tr -d &#x27;[:space:]&#x27; | tr &#x27;A-F&#x27; &#x27;a-f&#x27;)\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 转换Apache分组换行的校验值\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">printf\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;%s  %s\\\\\\\\n&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$EXPECTED_SHA512\\\\u003c/span>&quot;\\\\u003c/span> kafka_2.13-4.0.2.tgz | \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sha512sum\\\\u003c/span> -c - \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 必须看到OK，失败则停止\\\\u003c/span>\\\\ntar -xzf kafka_2.13-4.0.2.tgz                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 解压到当前目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> KAFKA_HOME=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PWD\\\\u003c/span>/kafka_2.13-4.0.2&quot;\\\\u003c/span>          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 保存安装位置\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> BS=127.0.0.1:9092                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 当前实验集群入口\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> TOPIC=orders                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实验主题\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">export\\\\u003c/span> GROUP=orders-worker                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实验消费者组\\\\u003c/span>\\\\nADMIN=()                                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 实验环境未开启认证\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cd\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$KAFKA_HOME\\\\u003c/span>&quot;\\\\u003c/span>                                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 进入安装目录\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">mkdir\\\\u003c/span> -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$HOME\\\\u003c/span>/kafka-lab/data&quot;\\\\u003c/span>                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 使用持久目录，避免 /tmp 被清理\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> &gt; config/lab.properties &lt;&lt;\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">EOF\\\\n# 单进程同时承担 Broker、Controller，只用于本机实验\\\\nprocess.roles=broker,controller\\\\nnode.id=1\\\\ncontroller.quorum.bootstrap.servers=127.0.0.1:9093\\\\nlisteners=PLAINTEXT://127.0.0.1:9092,CONTROLLER://127.0.0.1:9093\\\\nadvertised.listeners=PLAINTEXT://127.0.0.1:9092\\\\ninter.broker.listener.name=PLAINTEXT\\\\ncontroller.listener.names=CONTROLLER\\\\nlistener.security.protocol.map=CONTROLLER:PLAINTEXT,PLAINTEXT:PLAINTEXT\\\\nlog.dirs=$HOME/kafka-lab/data\\\\noffsets.topic.replication.factor=1\\\\ntransaction.state.log.replication.factor=1\\\\ntransaction.state.log.min.isr=1\\\\nEOF\\\\u003c/span>\\\\nCLUSTER_ID=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-subst\\\\\\">$(bin/kafka-storage.sh random-uuid)\\\\u003c/span>&quot;\\\\u003c/span>    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 仅初始化新实验集群时生成一次\\\\u003c/span>\\\\nbin/kafka-storage.sh format --standalone -t \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$CLUSTER_ID\\\\u003c/span>&quot;\\\\u003c/span> -c config/lab.properties \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 初始化全新空目录\\\\u003c/span>\\\\nbin/kafka-server-start.sh config/lab.properties    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 前台启动，保留这个终端\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：日志显示启动完成后，新开终端重新设置 \\\\u003ccode>KAFKA_HOME\\\\u003c/code>、\\\\u003ccode>BS\\\\u003c/code>、\\\\u003ccode>TOPIC\\\\u003c/code>、\\\\u003ccode>GROUP\\\\u003c/code> 和 \\\\u003ccode>ADMIN\\\\u003c/code>，再运行下一节。普通重启只执行最后一行；已有数据目录不重新生成集群 ID，也不再次格式化。前台服务按 Ctrl+C 会停止 Broker。\\\\u003c/p>\\\\n\\\\u003cp>下载、初始化和运行方式可对照 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/getting-started/quickstart/\\\\\\">Apache Kafka Quick Start\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003c/details>\\\\n\\\\u003ch3 id=\\\\\\"多节点部署要先明确什么\\\\\\">多节点部署要先明确什么\\\\u003c/h3>\\\\n\\\\u003cp>正式环境把 Controller 与 Broker 的角色、故障域和安全通道规划好，再初始化。常见规划是 3 个专用 Controller 和至少 3 个 Broker；3 个 Controller 需要至少 2 个正常才能形成多数派。增加 Broker 不等于增加 Controller。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>项目\\\\u003c/th>\\\\n\\\\u003cth>配置和检查重点\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>节点身份\\\\u003c/td>\\\\n\\\\u003ctd>全集群 \\\\u003ccode>node.id\\\\u003c/code> 唯一；重启保留原 ID 和原数据\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>集群身份\\\\u003c/td>\\\\n\\\\u003ctd>所有节点使用同一个 cluster ID；每个目录保留正确的 \\\\u003ccode>meta.properties\\\\u003c/code>\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>角色\\\\u003c/td>\\\\n\\\\u003ctd>\\\\u003ccode>process.roles=controller\\\\u003c/code> 或 \\\\u003ccode>broker\\\\u003c/code>；实验的合并模式不等于生产隔离\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Quorum\\\\u003c/td>\\\\n\\\\u003ctd>区分静态 \\\\u003ccode>controller.quorum.voters\\\\u003c/code> 和动态 quorum；按所用方式初始化和变更成员\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>地址\\\\u003c/td>\\\\n\\\\u003ctd>Broker 的广播地址对实际客户端可达；Controller 地址对节点可达\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>存储\\\\u003c/td>\\\\n\\\\u003ctd>数据、元数据目录持久化，服务用户有权限，监测空间和 inode\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>内部主题\\\\u003c/td>\\\\n\\\\u003ctd>在首次创建前规划 offsets、transaction 内部主题副本数；修改默认值不会自动增加已有主题副本\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>业务主题\\\\u003c/td>\\\\n\\\\u003ctd>例如副本数 3、\\\\u003ccode>min.insync.replicas=2\\\\u003c/code>，与生产者 \\\\u003ccode>acks=all\\\\u003c/code> 配合\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>安全\\\\u003c/td>\\\\n\\\\u003ctd>按已有 PKI/身份体系配置 TLS、SASL、ACL；不把明文实验端口暴露到公网\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>静态和动态 quorum 的初始化参数不同，尤其不能给已有集群的每个 Controller 分别运行 \\\\u003ccode>--standalone\\\\u003c/code>。新增节点和变更成员应按 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/operations/kraft/\\\\\\">KRaft 部署与成员管理\\\\u003c/a>执行。\\\\u003c/p>\\\\n\\\\u003ch3 id=\\\\\\"验证一次完整收发\\\\\\">验证一次完整收发\\\\u003c/h3>\\\\n\\\\u003cp>先确认第 1 节变量，在实验集群执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --create --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --partitions 3 --replication-factor 1 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 新建实验主题\\\\u003c/span>\\\\nbin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看分区和 Leader\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">printf\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;order-1001:created\\\\\\\\norder-1002:created\\\\\\\\n&#x27;\\\\u003c/span> | bin/kafka-console-producer.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --property parse.key=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span> --property key.separator=: --producer-property acks=all \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 写两条带 key 的消息\\\\u003c/span>\\\\nbin/kafka-console-consumer.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --from-beginning --max-messages 2 --timeout-ms 10000 --property print.key=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span> --property print.partition=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span> --property print.offset=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 限量读取验证\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：能读到两条订单事件才说明客户端到数据分区的收发路径通了。\\\\u003ccode>printf ... | ...\\\\u003c/code> 把左侧文字作为右侧标准输入；控制台退出不会删除消息。该验证命令没有使用业务消费者组，避免影响其分区分配与进度。安全集群为生产者、消费者分别补上对应的配置文件参数。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"3-故障先定位范围再改配置\\\\\\">3. 故障先定位范围，再改配置\\\\u003c/h2>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>现象\\\\u003c/th>\\\\n\\\\u003cth>建议执行顺序\\\\u003c/th>\\\\n\\\\u003cth>先找的证据\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>完全连不上\\\\u003c/td>\\\\n\\\\u003ctd>进程 → 监听 → DNS/TCP → Kafka API → 广播地址 → TLS/认证\\\\u003c/td>\\\\n\\\\u003ctd>端口归属、连接错误、元数据中的节点地址\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>主题不可用\\\\u003c/td>\\\\n\\\\u003ctd>describe → 无 Leader 分区 → 副本主机 → quorum → Broker 日志\\\\u003c/td>\\\\n\\\\u003ctd>Leader、ISR、存储错误、选举与 fencing\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>发送变慢\\\\u003c/td>\\\\n\\\\u003ctd>客户端队列 → Broker 请求分段耗时 → ISR → 磁盘/GC/网络\\\\u003c/td>\\\\n\\\\u003ctd>是本地处理慢，还是等待副本慢\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>消费积压\\\\u003c/td>\\\\n\\\\u003ctd>分区 Lag 趋势 → 成员分配 → 业务耗时 → poll/rebalance → Broker\\\\u003c/td>\\\\n\\\\u003ctd>热点分区、慢 SQL、线程阻塞、频繁重平衡\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>磁盘持续上涨\\\\u003c/td>\\\\n\\\\u003ctd>目录占用 → 主题策略 → 日志段 → cleaner/删除延迟 → 副本迁移\\\\u003c/td>\\\\n\\\\u003ctd>delete/compact、分区数量、未完成迁移\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>提交位移失败\\\\u003c/td>\\\\n\\\\u003ctd>组状态和协调器 → 内部主题 Leader/ISR → 加载日志 → 客户端 ownership\\\\u003c/td>\\\\n\\\\u003ctd>是业务失败、组变更，还是协调器不可用\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>先保存事发时间、涉及主题/分区/组、错误码、最近变更和监控截图。重启会改变线程、连接与部分现场，先收集这些证据。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"4-服务突然不可用连不上\\\\\\">4. 服务突然不可用、连不上\\\\u003c/h2>\\\\n\\\\u003cp>在 Broker 主机执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">date\\\\u003c/span> -Is                                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 记录主机时间并与应用侧时间对齐\\\\u003c/span>\\\\npgrep -af \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;kafka.Kafka&#x27;\\\\u003c/span>                           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查找 Broker JVM，避免仅按 java 判断\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> ss -lntp \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;sport = :9092&#x27;\\\\u003c/span>                     \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认客户端端口和进程归属\\\\u003c/span>\\\\nsystemctl status kafka --no-pager -l              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看服务状态与退出结果\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u kafka --since \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;30 minutes ago&#x27;\\\\u003c/span> --no-pager \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看退出、启动和错误日志\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -k --since \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;30 minutes ago&#x27;\\\\u003c/span> --no-pager | grep -Ei \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;oom|out of memory|killed process|I/O error|read-only&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查内核杀进程及磁盘错误\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>Killed process ... java\\\\u003c/code> 是内核 OOM 的证据；systemd 的 \\\\u003ccode>status=15/TERM\\\\u003c/code> 只说明终止信号，单凭它不能证明是谁停止的。追查人为操作还要结合已有 sudo、审计、SSH 和发布平台记录；未提前启用审计时，往往无法事后还原发送信号的人。\\\\u003c/p>\\\\n\\\\u003cp>在\\\\u003cstrong>出问题的客户端主机\\\\u003c/strong>执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">getent hosts broker1.example.com                  \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查实际客户端使用的 DNS 解析\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">timeout\\\\u003c/span> 3 bash -c \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;exec 3&lt;&gt;/dev/tcp/broker1.example.com/9092&#x27;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只验证 TCP 建连，退出码0代表连通\\\\u003c/span>\\\\nbin/kafka-broker-api-versions.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 验证 Kafka 协议并观察返回节点\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：TCP 成功但 Kafka API 超时，继续检查协议、TLS、认证与广播地址。\\\\u003ccode>bootstrap.servers\\\\u003c/code> 只是入口，客户端获取元数据后会连接分区 Leader、协调器等其他 Broker。常见情况是入口可达，但 \\\\u003ccode>advertised.listeners\\\\u003c/code> 返回容器主机名、\\\\u003ccode>localhost\\\\u003c/code> 或另一网络的地址。\\\\u003c/p>\\\\n\\\\u003cp>\\\\u003ccode>listeners\\\\u003c/code> 管本地绑定，\\\\u003ccode>advertised.listeners\\\\u003c/code> 管对客户端公布什么地址；广播地址不能写 \\\\u003ccode>0.0.0.0\\\\u003c/code>。多网络场景要分监听器配置，改完从每个实际客户端网络重新验证全部节点。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">openssl s_client -connect broker1.example.com:9093 -servername broker1.example.com -verify_hostname broker1.example.com -CAfile /path/to/ca.pem -verify_return_error &lt; /dev/null \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 对已有TLS端口检查证书链和主机名\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：证书 SAN 不包含广播主机名时，修证书或地址，不清空 \\\\u003ccode>ssl.endpoint.identification.algorithm\\\\u003c/code> 来跳过验证。TLS 握手通过仍不代表 SASL 登录和 ACL 授权通过。\\\\u003c/p>\\\\n\\\\u003cp>CentOS 7的旧OpenSSL先用 \\\\u003ccode>openssl s_client -help\\\\u003c/code> 核对选项；若不支持 \\\\u003ccode>-verify_hostname\\\\u003c/code>，在具有相应能力的管理机执行这条检查。Kafka端口不是HTTP接口，不能改用curl的HTTPS响应来验收；仅删除主机名参数后握手成功，也不代表域名验证通过。最终还需用原Kafka客户端的TLS/SASL配置验证连接。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"5-leader-不可用isr-收缩\\\\\\">5. Leader 不可用、ISR 收缩\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看每个分区 Leader、Replicas、Isr\\\\u003c/span>\\\\nbin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --unavailable-partitions \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只列无可用 Leader 的分区\\\\u003c/span>\\\\nbin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --under-replicated-partitions \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 列出同步副本不足的分区\\\\u003c/span>\\\\nbin/kafka-metadata-quorum.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> describe --status \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># KRaft：查看元数据多数派状态\\\\u003c/span>\\\\nbin/kafka-metadata-quorum.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> describe --replication \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># KRaft：查看各元数据副本追赶情况\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>Replicas: 1,2,3\\\\u003c/code>、\\\\u003ccode>Isr: 1,2\\\\u003c/code> 表示副本 3 未在同步集合中，不等于主题已丢失。若 \\\\u003ccode>min.insync.replicas=2\\\\u003c/code>，再失去一个同步副本时，\\\\u003ccode>acks=all\\\\u003c/code> 写入可能失败，这是保护可靠性的行为。\\\\u003c/p>\\\\n\\\\u003cp>按输出中的 Broker ID 找到主机，检查磁盘、网络、GC、抓取线程错误与重启记录。如果只有个别分区异常，先查这些副本；大量主题同时无 Leader，再重点查 Broker 故障和 Controller quorum。Quorum 的 HighWatermark 与业务分区高水位是两套数据，不能相互替代。\\\\u003c/p>\\\\n\\\\u003cp>处理顺序：恢复磁盘和节点连通 → 恢复正常副本抓取 → 等待 ISR 回来 → 再验证收发与错误率。不要把启用非 ISR 副本选举、降低 min ISR、删除元数据目录当成常规恢复动作；这些会改变数据保留或可靠性结果。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"6-消费积压先看哪个分区哪个成员慢\\\\\\">6. 消费积压：先看哪个分区、哪个成员慢\\\\u003c/h2>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-consumer-groups.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --group \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$GROUP\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看各分区提交进度及 Lag\\\\u003c/span>\\\\nbin/kafka-consumer-groups.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --group \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$GROUP\\\\u003c/span>&quot;\\\\u003c/span> --members --verbose \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看成员及其分区分配\\\\u003c/span>\\\\nbin/kafka-consumer-groups.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --group \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$GROUP\\\\u003c/span>&quot;\\\\u003c/span> --state \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看状态、协调器与成员数\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：只有分区 2 的 Lag 增长，且一直由同一个成员负责，优先查该分区 key 热点和对应业务处理；所有分区都增长，则核对输入速率、总消费能力、下游容量。至少间隔一段时间采样两次，单点 Lag 不能表示趋势。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>字段/状态\\\\u003c/th>\\\\n\\\\u003cth>怎么理解\\\\u003c/th>\\\\n\\\\u003cth>下一步\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>CURRENT-OFFSET\\\\u003c/td>\\\\n\\\\u003ctd>已提交的下一条消费位置，不一定是进程最新处理位置\\\\u003c/td>\\\\n\\\\u003ctd>检查提交是否失败、是否过久才提交\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>LOG-END-OFFSET / LAG\\\\u003c/td>\\\\n\\\\u003ctd>工具显示的末端位置与提交位置差\\\\u003c/td>\\\\n\\\\u003ctd>位移空洞、事务和压实会影响计数，结合消息年龄\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>成员无分区\\\\u003c/td>\\\\n\\\\u003ctd>实例数可能超过可分配分区数，也可能订阅不同\\\\u003c/td>\\\\n\\\\u003ctd>加实例之前先看分配结果\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Preparing/CompletingRebalance\\\\u003c/td>\\\\n\\\\u003ctd>classic 组正在重平衡\\\\u003c/td>\\\\n\\\\u003ctd>查 poll 超时、成员启停、订阅变化\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Empty\\\\u003c/td>\\\\n\\\\u003ctd>该组目前没有活跃成员，可能仍有位移\\\\u003c/td>\\\\n\\\\u003ctd>查应用是否正常运行、是否连错集群\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>积压恢复要估算时间：假设新增 5 万条/秒，持续处理能力 8 万条/秒，净追赶速度只有 3 万条/秒。900 万条积压约需 300 秒，前提是这些速率稳定且 Lag 可近似计数。还要确保最旧未消费消息不会在追赶过程中超过留存期。\\\\u003c/p>\\\\n\\\\u003cp>处理优先级：修复下游瓶颈和失败重试风暴 → 降低单次 poll 处理时间或批量处理 → 在分区允许范围内扩消费者 → 再评估分区扩容。直接把位移调到最新会跳过业务数据，不是消除积压的通用方案。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"7-磁盘上涨留存不生效\\\\\\">7. 磁盘上涨、留存不生效\\\\u003c/h2>\\\\n\\\\u003cp>在 Broker 主机上，把 \\\\u003ccode>/var/lib/kafka\\\\u003c/code> 改成实际数据挂载点：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -hT /var/lib/kafka                             \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查文件系统空间与类型\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">df\\\\u003c/span> -i /var/lib/kafka                              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查 inode，空间未满也可能写不了文件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">du\\\\u003c/span> -xhd1 /var/lib/kafka                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 统计同一文件系统下各分区目录占用\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> lsof +L1                                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查已删除但仍被进程持有的文件\\\\u003c/span>\\\\niostat -xz 1 5                                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 连续观察磁盘等待、吞吐和队列\\\\u003c/span>\\\\nbin/kafka-log-dirs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --topic-list \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查每个副本大小和目录错误\\\\u003c/span>\\\\nbin/kafka-configs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --entity-type topics --entity-name \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --describe --all \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看主题实际配置和继承来源\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>df\\\\u003c/code> 大而 \\\\u003ccode>du\\\\u003c/code> 小，先查已删除文件、挂载点和其他目录；\\\\u003ccode>du\\\\u003c/code> 的分区目录明显变大，则检查以下规则。\\\\u003c/p>\\\\n\\\\u003cul>\\\\n\\\\u003cli>\\\\u003ccode>retention.bytes\\\\u003c/code> 是\\\\u003cstrong>每个分区\\\\u003c/strong>的留存阈值，整个集群还要乘上分区数量与副本数，并留出额外空间。\\\\u003c/li>\\\\n\\\\u003cli>\\\\u003ccode>delete\\\\u003c/code> 按日志段回收，不是逐条消息到点立即删；段切分、检查周期、删除延迟和复制状态都会影响回收时点。\\\\u003c/li>\\\\n\\\\u003cli>\\\\u003ccode>compact\\\\u003c/code> 保留每个 key 的最新状态，不表示按时间删除所有旧消息；\\\\u003ccode>compact,delete\\\\u003c/code> 同时有时间/大小保留约束。\\\\u003c/li>\\\\n\\\\u003cli>\\\\u003ccode>null\\\\u003c/code> value 的 tombstone 参与压实删除；字符串 \\\\u003ccode>&quot;null&quot;\\\\u003c/code> 和空字符串不是 tombstone。\\\\u003c/li>\\\\n\\\\u003cli>\\\\u003ccode>segment.bytes\\\\u003c/code>/\\\\u003ccode>segment.ms\\\\u003c/code> 太大时，小流量主题回收粒度可能很粗；频繁切小段又会增加文件与恢复开销。\\\\u003c/li>\\\\n\\\\u003cli>副本迁移中的 future 目录、cleaner 临时文件、内部主题，也会占空间；不要手工删除这些文件。\\\\u003c/li>\\\\n\\\\u003c/ul>\\\\n\\\\u003cp>需要临时调整业务主题留存时，先保存旧配置、确认最慢消费者和补数据需求，再执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-configs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --entity-type topics --entity-name \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --describe --all &gt; topic-config.before.txt \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 保存变更前配置供人工核对\\\\u003c/span>\\\\nbin/kafka-configs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --entity-type topics --entity-name \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --alter --add-config retention.ms=259200000 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 示例：明确批准后改为3天，会使旧数据有资格被删\\\\u003c/span>\\\\nbin/kafka-configs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --entity-type topics --entity-name \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --describe --all \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 核对配置已生效\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：回退必须恢复原来的值；原先没有主题级覆盖才用 \\\\u003ccode>--delete-config retention.ms\\\\u003c/code> 恢复继承。把留存改长无法找回已经删除的数据。参数含义见 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/configuration/topic-level-configs/\\\\\\">主题配置\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"8-发送变慢cpu-或-gc-异常\\\\\\">8. 发送变慢、CPU 或 GC 异常\\\\u003c/h2>\\\\n\\\\u003cp>在 Broker 主机执行，先从进程列表确认 PID，不自动拿到多个 JVM 后直接操作：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">pgrep -af \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;kafka.Kafka&#x27;\\\\u003c/span>                           \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 找到本次检查的 JVM\\\\u003c/span>\\\\nPID=12345                                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 替换成已确认的 Broker PID\\\\u003c/span>\\\\nps -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PID\\\\u003c/span>&quot;\\\\u003c/span> -o pid,ppid,user,etime,%cpu,%mem,args \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认进程身份和运行时间\\\\u003c/span>\\\\npidstat -p \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PID\\\\u003c/span>&quot;\\\\u003c/span> -u -r -d 1 5                    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 按进程看 CPU、内存缺页和 I/O\\\\u003c/span>\\\\nvmstat 1 5                                       \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 看运行队列、swap、阻塞与CPU等待\\\\u003c/span>\\\\niostat -xz 1 5                                   \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 与磁盘负载同时对照\\\\u003c/span>\\\\njcmd \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PID\\\\u003c/span>&quot;\\\\u003c/span> Thread.\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">print\\\\u003c/span> -l &gt; kafka-threads.txt    \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 服务用户执行，保存线程栈\\\\u003c/span>\\\\njcmd \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$PID\\\\u003c/span>&quot;\\\\u003c/span> GC.heap_info                          \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 服务用户执行，查看当前堆状态\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>jcmd\\\\u003c/code> 需要同机、匹配权限，并通常使用相应 JDK；容器中还涉及 PID 命名空间。\\\\u003ccode>&gt; kafka-threads.txt\\\\u003c/code> 把标准输出保存到文件，会覆盖同名文件。先用现有 GC 日志和监控，不为了一次观测在生产环境强制 Full GC 或直接抓超大 heap dump。\\\\u003c/p>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>证据\\\\u003c/th>\\\\n\\\\u003cth>优先排查\\\\u003c/th>\\\\n\\\\u003cth>变更后的验证\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>RequestQueueTimeMs 高\\\\u003c/td>\\\\n\\\\u003ctd>I/O处理线程是否忙、CPU/磁盘是否已饱和\\\\u003c/td>\\\\n\\\\u003ctd>队列降低且请求延迟改善\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>LocalTimeMs 高\\\\u003c/td>\\\\n\\\\u003ctd>日志写入、压缩/转换、授权、锁竞争\\\\u003c/td>\\\\n\\\\u003ctd>具体慢步骤耗时下降\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>Produce RemoteTimeMs 高\\\\u003c/td>\\\\n\\\\u003ctd>Follower 磁盘、网络、抓取进度、ISR\\\\u003c/td>\\\\n\\\\u003ctd>副本追上且发送超时下降\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>ResponseQueue/SendTime 高\\\\u003c/td>\\\\n\\\\u003ctd>网络线程、出口带宽、客户端读响应\\\\u003c/td>\\\\n\\\\u003ctd>排队与重传下降\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>客户端 buffer 等待高\\\\u003c/td>\\\\n\\\\u003ctd>Broker慢、元数据不可达、生产速率超出能力\\\\u003c/td>\\\\n\\\\u003ctd>重试和排队消退、最终回调成功\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>大量 major fault、读I/O增大\\\\u003c/td>\\\\n\\\\u003ctd>页缓存不足、回放历史数据、其他进程争抢内存\\\\u003c/td>\\\\n\\\\u003ctd>热业务延迟恢复\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>吞吐和延迟先各自给目标，再逐项实验。保留可靠性要求，用批次、压缩和并行度改善效率；不通过关闭重试或把 \\\\u003ccode>acks\\\\u003c/code> 改成 0 来掩盖故障。堆要给页缓存、线程栈、直接内存和容器限制留余量，不把“固定 6GB 堆”当通用答案。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"9-扩分区迁移副本与下线节点\\\\\\">9. 扩分区、迁移副本与下线节点\\\\u003c/h2>\\\\n\\\\u003cp>扩分区只增加并行度，不会自动重分布历史数据。同一 key 的新消息可能切换分区，先评估顺序、去重、流处理关联以及下游容量。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 记录原分区数与副本分布\\\\u003c/span>\\\\nbin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --alter --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> --partitions 6 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 示例：由3增到6，不能原地缩回\\\\u003c/span>\\\\nbin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 验证新分区都有 Leader 和 ISR\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>副本迁移适用于 Broker 扩容、磁盘失衡、调整副本数和下线。以至少 3 个 Broker 的集群为前提，目标 ID 必须真实存在，下面以 ID 1、2、3、4 为例：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">cat\\\\u003c/span> &gt; topics-to-move.json &lt;&lt;\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;EOF&#x27;\\\\u003c/span>\\\\n{\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;version&quot;\\\\u003c/span>:1,\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;topics&quot;\\\\u003c/span>:[{\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;topic&quot;\\\\u003c/span>:\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;orders&quot;\\\\u003c/span>}]}\\\\nEOF\\\\nbin/kafka-reassign-partitions.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --topics-to-move-json-file topics-to-move.json --broker-list \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&#x27;2,3,4&#x27;\\\\u003c/span> --generate &gt; reassignment-plan.txt \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 只生成方案，包含当前和建议分配\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：阅读输出，把“当前分配”保存为 \\\\u003ccode>reassignment-before.json\\\\u003c/code>，把审核后的“建议分配”保存为 \\\\u003ccode>reassignment-after.json\\\\u003c/code>，均只保留对应 JSON。不能直接把整份带说明文字的输出当 JSON。核对每个分区仍有足够副本、目标故障域与磁盘空间，再执行：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-reassign-partitions.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --reassignment-json-file reassignment-after.json --execute --throttle 10485760 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 示例：每秒10MiB迁移限速，按实际余量调整\\\\u003c/span>\\\\nbin/kafka-reassign-partitions.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --reassignment-json-file reassignment-after.json --verify \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查完成情况；完成后按工具行为清除本次迁移限速\\\\u003c/span>\\\\nbin/kafka-log-dirs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --topic-list \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 验证实际落盘位置、future副本及错误\\\\u003c/span>\\\\nbin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 验证最终副本列表与 ISR\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：加了 Broker 不会自动迁走旧数据；Broker 下线前要确认它承载的\\\\u003cstrong>所有业务与内部主题副本\\\\u003c/strong>已迁移，而不是只看 \\\\u003ccode>orders\\\\u003c/code>。回退使用之前保存的分配方案重新迁移，也需要时间和容量，并非瞬间撤销。迁移期间继续观察 Lag 和延迟，不能把限速设得低到副本永远追不上新增数据。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"10-动态配置自启与滚动维护\\\\\\">10. 动态配置、自启与滚动维护\\\\u003c/h2>\\\\n\\\\u003cp>先从实际生效配置判断来源：主题覆盖、单 Broker 动态配置、集群动态默认、静态文件及内置默认值可能不同。修改配置文件并不保证覆盖了动态值。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-configs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --entity-type brokers --entity-default --describe \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看集群动态默认\\\\u003c/span>\\\\nbin/kafka-configs.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --entity-type brokers --entity-name 1 --describe --all \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看Broker 1的配置及来源\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：是否能动态更新取决于本版本参数的 Update Mode，不能因为旧版本支持动态修改就认为 4.x 也支持。只读配置需要按计划滚动重启，见 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/configuration/broker-configs/\\\\\\">Broker 配置说明\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003cdetails class=\\\\\\"install-guide\\\\\\">\\\\n\\\\u003csummary>展开：二进制部署的 systemd 服务模板\\\\u003c/summary>\\\\n\\\\u003cp>仅用于尚无服务托管的新实例。先准备专用 \\\\u003ccode>kafka\\\\u003c/code> 用户、真实 JDK 路径、配置、持久目录和权限，并完成新集群初始化；不与已有容器、脚本守护或 systemd 实例重复启动。将下面内容保存为 \\\\u003ccode>/etc/systemd/system/kafka.service\\\\u003c/code>，按实际路径调整。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-ini\\\\\\">\\\\u003cspan class=\\\\\\"hljs-section\\\\\\">[Unit]\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">Description\\\\u003c/span>=Apache Kafka\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">After\\\\u003c/span>=network-\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">on\\\\u003c/span>line.target\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">Wants\\\\u003c/span>=network-\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">on\\\\u003c/span>line.target\\\\n\\\\n\\\\u003cspan class=\\\\\\"hljs-section\\\\\\">[Service]\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">Type\\\\u003c/span>=simple\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">User\\\\u003c/span>=kafka\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">Group\\\\u003c/span>=kafka\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">WorkingDirectory\\\\u003c/span>=/opt/kafka\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">Environment\\\\u003c/span>=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;JAVA_HOME=/path/to/jdk-17&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">Environment\\\\u003c/span>=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;KAFKA_HEAP_OPTS=-Xms1g -Xmx1g&quot;\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">ExecStart\\\\u003c/span>=/opt/kafka/bin/kafka-server-start.sh /etc/kafka/server.properties\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">Restart\\\\u003c/span>=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">on\\\\u003c/span>-failure\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">RestartSec\\\\u003c/span>=\\\\u003cspan class=\\\\\\"hljs-number\\\\\\">10\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">TimeoutStopSec\\\\u003c/span>=\\\\u003cspan class=\\\\\\"hljs-number\\\\\\">180\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">LimitNOFILE\\\\u003c/span>=\\\\u003cspan class=\\\\\\"hljs-number\\\\\\">100000\\\\u003c/span>\\\\n\\\\n\\\\u003cspan class=\\\\\\"hljs-section\\\\\\">[Install]\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-attr\\\\\\">WantedBy\\\\u003c/span>=multi-user.target\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：1GiB 堆和文件句柄数只是起始模板，应结合分区规模与限制调整。\\\\u003ccode>Type=simple\\\\u003c/code> 的启动命令不加 \\\\u003ccode>-daemon\\\\u003c/code>、\\\\u003ccode>nohup\\\\u003c/code> 或 \\\\u003ccode>&amp;\\\\u003c/code>，让 systemd 跟踪实际进程。检查现有 log4j 配置中的日志目录是否允许 \\\\u003ccode>kafka\\\\u003c/code> 用户写入。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemd-analyze verify /etc/systemd/system/kafka.service \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 校验单元文件\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl daemon-reload                      \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 重新载入服务定义\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl \\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">enable\\\\u003c/span> --now kafka                 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 新实例启用自启并启动\\\\u003c/span>\\\\nsystemctl status kafka --no-pager -l              \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看启动结果\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u kafka -n 100 --no-pager         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 检查日志与权限错误\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003c/details>\\\\n\\\\u003cp>滚动维护一次只操作一个节点：确认无不可用分区、ISR 和容量正常 → 保存配置 → 优雅停止 → 更新 → 启动 → 等待副本追上 → 验证收发和错误率 → 再进行下一个。Controller 还要保证多数派存活。\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl stop kafka                         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 在已确认的目标节点优雅停止\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> systemctl start kafka                        \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 完成该节点维护后启动\\\\u003c/span>\\\\n\\\\u003cspan class=\\\\\\"hljs-built_in\\\\\\">sudo\\\\u003c/span> journalctl -u kafka -n 100 --no-pager         \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 确认恢复过程无持续错误\\\\u003c/span>\\\\nbin/kafka-topics.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --describe --under-replicated-partitions \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 等待该次维护带来的ISR不足消退\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：重启不会重新 format 数据目录。版本升级还涉及客户端兼容性、\\\\u003ccode>metadata.version\\\\u003c/code>、事务/组协议等条件；先按目标版本升级文档完成预检和回退设计，不能把换二进制包等同于完整升级。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"11-安全和监控分清问题在哪一层\\\\\\">11. 安全和监控：分清问题在哪一层\\\\u003c/h2>\\\\n\\\\u003ctable>\\\\n\\\\u003cthead>\\\\n\\\\u003ctr>\\\\n\\\\u003cth>报错\\\\u003c/th>\\\\n\\\\u003cth>检查位置\\\\u003c/th>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/thead>\\\\n\\\\u003ctbody>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>SSLHandshakeException\\\\u003c/td>\\\\n\\\\u003ctd>信任链、有效期、SAN、监听协议、双向证书要求\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>SaslAuthenticationException\\\\u003c/td>\\\\n\\\\u003ctd>SASL机制、用户、凭据文件、服务端认证配置\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>TopicAuthorizationException\\\\u003c/td>\\\\n\\\\u003ctd>实际 principal 对该 Topic 的操作权限\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>GroupAuthorizationException\\\\u003c/td>\\\\n\\\\u003ctd>该 principal 对目标 \\\\u003ca href=\\\\\\"http://group.id\\\\\\">group.id\\\\u003c/a> 的权限\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003ctr>\\\\n\\\\u003ctd>TransactionalIdAuthorizationException\\\\u003c/td>\\\\n\\\\u003ctd>\\\\u003ca href=\\\\\\"http://transactional.id\\\\\\">transactional.id\\\\u003c/a> 对应的授权\\\\u003c/td>\\\\n\\\\u003c/tr>\\\\n\\\\u003c/tbody>\\\\n\\\\u003c/table>\\\\n\\\\u003cp>KRaft ACL 使用 \\\\u003ccode>org.apache.kafka.metadata.authorizer.StandardAuthorizer\\\\u003c/code>。不要直接复制旧版 ZooKeeper authorizer 配置。已有安全集群由管理员使用管理凭据执行最小授权：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-acls.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --list --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看目标主题ACL\\\\u003c/span>\\\\nbin/kafka-acls.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --list --group \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$GROUP\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 查看消费者组ACL\\\\u003c/span>\\\\nbin/kafka-acls.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --add --allow-principal User:orders-reader --operation Read --operation Describe --topic \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$TOPIC\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 示例：授予主题读取权限\\\\u003c/span>\\\\nbin/kafka-acls.sh --bootstrap-server \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">${ADMIN[@]}\\\\u003c/span>&quot;\\\\u003c/span> --add --allow-principal User:orders-reader --operation Read --group \\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$GROUP\\\\u003c/span>&quot;\\\\u003c/span> \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 示例：授予指定组读取权限\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：\\\\u003ccode>orders-reader\\\\u003c/code> 必须是认证后实际得到的 principal 名称；TLS DN 映射可能改变它。权限变更后用这个用户验证，而非继续使用管理员。认证、加密、授权分别配置，不能用开放全部 ACL 或把业务用户设为 super user 来处理授权错误。参照 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/security/authorization-and-acls/\\\\\\">ACL 配置\\\\u003c/a>和 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/security/encryption-and-authentication-using-ssl/\\\\\\">TLS 配置\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003cp>监控同时覆盖业务与基础设施：端到端处理延迟、错误/重试率、各分区 Lag 与消息年龄、ISR/离线分区、请求分段耗时、磁盘剩余时间、GC、网络重传、Controller quorum 健康。按版本和角色选择指标，详见 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/operations/monitoring/\\\\\\">Kafka 监控指标\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003cp>已有 Prometheus/JMX Exporter/Grafana 体系优先复用。启用远程 JMX 时配置认证、TLS 和网络访问范围；不要把无认证 JMX 暴露出去。监控 Kafka 端收发成功还不够，应有独立的轻量端到端探测，验证业务链路实际可用。\\\\u003c/p>\\\\n\\\\u003ch2 id=\\\\\\"12-容量压测和跨集群恢复\\\\\\">12. 容量、压测和跨集群恢复\\\\u003c/h2>\\\\n\\\\u003cp>容量先用真实压缩后的流量测量：单副本写入速率 × 留存秒数 × 副本数，再加索引、内部主题、段回收波动、迁移空间和故障余量。热点分区单独估算；总容量够不代表最满那块盘够。网络还要计算副本同步、每个消费者组读取与跨集群复制。\\\\u003c/p>\\\\n\\\\u003cp>只在专用测试主题和批准的窗口压测，下面前提是已创建 \\\\u003ccode>kafka-bench\\\\u003c/code>，且其留存与容量可控：\\\\u003c/p>\\\\n\\\\u003cpre>\\\\u003ccode class=\\\\\\"hljs language-bash\\\\\\">bin/kafka-producer-perf-test.sh --topic kafka-bench --num-records 100000 --record-size 1024 --throughput 1000 --producer-props bootstrap.servers=\\\\u003cspan class=\\\\\\"hljs-string\\\\\\">&quot;\\\\u003cspan class=\\\\\\"hljs-variable\\\\\\">$BS\\\\u003c/span>&quot;\\\\u003c/span> acks=all enable.idempotence=\\\\u003cspan class=\\\\\\"hljs-literal\\\\\\">true\\\\u003c/span> compression.type=lz4 \\\\u003cspan class=\\\\\\"hljs-comment\\\\\\"># 固定输入速率测试，约100MiB原始载荷\\\\u003c/span>\\\\n\\\\u003c/code>\\\\u003c/pre>\\\\n\\\\u003cp>示例：安全集群另传 \\\\u003ccode>--producer.config &quot;$CLIENT_CONFIG&quot;\\\\u003c/code>。用符合生产可靠性要求的配置，记录 p95/p99、错误率、ISR、磁盘和 CPU；不要只用平均延迟或一次峰值承诺 SLA。\\\\u003c/p>\\\\n\\\\u003cp>跨集群使用 MirrorMaker 2 等复制链路时，先定义要复制的主题、方向、命名规则和故障切换方案。目标分区数、授权、消费位移转换以及恢复顺序都要验证；不能把源集群 offset 原样当成目标 offset，也不要盲目复制内部位移主题覆盖目标状态。\\\\u003c/p>\\\\n\\\\u003cp>复制不等于备份：误删和错误数据可能沿复制链路传播。保留独立恢复手段，并演练停止源写入、等待复制、转换消费位移、切换入口和验证业务去重的完整过程。双向复制还需防循环。实现细节参照 \\\\u003ca href=\\\\\\"https://kafka.apache.org/40/operations/geo-replication-cross-cluster-data-mirroring/\\\\\\">跨集群复制\\\\u003c/a>。\\\\u003c/p>\\\\n\\\\u003c/article>\\\\u003cdiv class=\\\\\\"article-end\\\\\\">\\\\u003cspan>— 本文结束 —\\\\u003c/span>\\\\u003ca href=\\\\\\"../index.html\\\\\\">返回知识库首页 ↗\\\\u003c/a>\\\\u003c/div>\\",\\"toc\\":[{\\"title\\":\\"1. 执行前先确认环境和权限\\",\\"level\\":2,\\"id\\":\\"1-执行前先确认环境和权限\\"},{\\"title\\":\\"2. 新建一个可以验证收发的实验环境\\",\\"level\\":2,\\"id\\":\\"2-新建一个可以验证收发的实验环境\\"},{\\"title\\":\\"多节点部署要先明确什么\\",\\"level\\":3,\\"id\\":\\"多节点部署要先明确什么\\"},{\\"title\\":\\"验证一次完整收发\\",\\"level\\":3,\\"id\\":\\"验证一次完整收发\\"},{\\"title\\":\\"3. 故障先定位范围，再改配置\\",\\"level\\":2,\\"id\\":\\"3-故障先定位范围再改配置\\"},{\\"title\\":\\"4. 服务突然不可用、连不上\\",\\"level\\":2,\\"id\\":\\"4-服务突然不可用连不上\\"},{\\"title\\":\\"5. Leader 不可用、ISR 收缩\\",\\"level\\":2,\\"id\\":\\"5-leader-不可用isr-收缩\\"},{\\"title\\":\\"6. 消费积压：先看哪个分区、哪个成员慢\\",\\"level\\":2,\\"id\\":\\"6-消费积压先看哪个分区哪个成员慢\\"},{\\"title\\":\\"7. 磁盘上涨、留存不生效\\",\\"level\\":2,\\"id\\":\\"7-磁盘上涨留存不生效\\"},{\\"title\\":\\"8. 发送变慢、CPU 或 GC 异常\\",\\"level\\":2,\\"id\\":\\"8-发送变慢cpu-或-gc-异常\\"},{\\"title\\":\\"9. 扩分区、迁移副本与下线节点\\",\\"level\\":2,\\"id\\":\\"9-扩分区迁移副本与下线节点\\"},{\\"title\\":\\"10. 动态配置、自启与滚动维护\\",\\"level\\":2,\\"id\\":\\"10-动态配置自启与滚动维护\\"},{\\"title\\":\\"11. 安全和监控：分清问题在哪一层\\",\\"level\\":2,\\"id\\":\\"11-安全和监控分清问题在哪一层\\"},{\\"title\\":\\"12. 容量、压测和跨集群恢复\\",\\"level\\":2,\\"id\\":\\"12-容量压测和跨集群恢复\\"}],\\"standaloneTitle\\":\\"\\"}"},"headers":[],"relativePath":"articles/kafka-operations.md","filePath":"articles/kafka-operations.md"}'),u={name:"articles/kafka-operations.md"};function n(t,e,l,p,o,r){return c(),a("div")}const h=s(u,[["render",n]]);export{d as __pageData,h as default};
